import{R as e,e as o,f as n,U as l}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"Flowlu","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/flowlu.md","filePath":"integrations/crm/flowlu.md","lastUpdated":1775908585000}'),i={name:"integrations/crm/flowlu.md"};function a(r,t,s,h,c,g){return o(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="flowlu" tabindex="-1">Flowlu <a class="header-anchor" href="#flowlu" aria-label="Permalink to &quot;Flowlu&quot;">​</a></h1><p>Follow the below steps to connect to the Flowlu API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Flowlu as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-flowlu-api" tabindex="-1">Step 2. Connect to the Flowlu API <a class="header-anchor" href="#step-2-connect-to-the-flowlu-api" aria-label="Permalink to &quot;Step 2. Connect to the Flowlu API&quot;">​</a></h3><ol><li>Go to <a href="https://flowlu.com/" target="_blank">Flowlu</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Portal Settings</strong>.</li><li>In the left-hand sidebar, click <strong>API Settings</strong>.</li><li>Click the <strong>Add</strong> button.</li><li>Select all applications and click the <strong>Save</strong> button.</li><li>Copy the <strong>API Key</strong> from Flowlu and paste in the <strong>API Key</strong> field in Formie.</li><li>Enter the full domain (including <code>https://</code>) for your Flowlu account in the <strong>Domain</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const p=e(i,[["render",a]]);export{u as __pageData,p as default};
